#include <stdio.h>
#include <string.h>

int days_in_month(int month, int year) {
    if (month == 2) {
        if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0)
            return 29;
        else
            return 28;
    } else if (month == 4 || month == 6 || month == 9 || month == 11)
        return 30;
    else
        return 31;
}

int validate_date(char *date) {
    int day, month, year;
    sscanf(date, "%d-%d-%d", &day, &month, &year);
    if (month < 1 || month > 12)
        return 0;
    if (day < 1 || day > days_in_month(month, year))
        return 0;
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("INVALID\n");
        return 1;
    }
    char *date = argv[1];
    if (strlen(date) != 10)
        printf("INVALID\n");
    else if (validate_date(date))
        printf("VALID\n");
    else
        printf("INVALID\n");
    return 0;
}
